import{_ as t}from"./chunks/geoml-archi.BT6sIk6p.js";import{_ as r,o as a,c as o,a0 as n}from"./chunks/framework.Ckbw5VQO.js";const g=JSON.parse('{"title":"GeoML","description":"","frontmatter":{},"headers":[],"relativePath":"fr/about/introduction.md","filePath":"fr/about/introduction.md"}'),s={name:"fr/about/introduction.md"};function i(l,e,c,d,u,p){return a(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="geoml" tabindex="-1">GeoML <a class="header-anchor" href="#geoml" aria-label="Permalink to &quot;GeoML&quot;">​</a></h1><p><strong>GeoML</strong> est un projet appliqué de machine learning géospatial : entraîner des modèles de détection d&#39;objets sur de vraies images aériennes, les exporter en <a href="https://onnx.ai/" target="_blank" rel="noreferrer">ONNX</a>, et livrer un SPA 100 % statique qui exécute l&#39;inférence directement dans le navigateur, sans backend.</p><img src="'+t+'" style="display:block;margin:2rem auto;width:100%;"><ul><li><strong>Un SPA React</strong> pilote la carte (<a href="https://maplibre.org/projects/gl-js/" target="_blank" rel="noreferrer">MapLibre</a>) et exécute l&#39;<a href="https://www.oracle.com/fr/artificial-intelligence/ai-inference/" target="_blank" rel="noreferrer">inférence</a> localement via <a href="https://onnxruntime.ai/docs/tutorials/web/" target="_blank" rel="noreferrer">ONNX Runtime Web</a>. Les couches de tuiles (<a href="https://cartes.gouv.fr/aide/fr/guides-utilisateur/utiliser-les-services-de-la-geoplateforme/diffusion/wmts/" target="_blank" rel="noreferrer">IGN WMTS</a>, <a href="https://wiki.openstreetmap.org/wiki/Main_Page" target="_blank" rel="noreferrer">OSM</a> …) sont appelées directement depuis le navigateur.</li><li><strong>Un pipeline d&#39;entraînement offline</strong> télécharge des tuiles satellitaires IGN et des polygones BD TOPO/OSM, génère automatiquement un dataset annoté au <a href="https://docs.ultralytics.com/datasets/detect#supported-dataset-formats" target="_blank" rel="noreferrer">format YOLO</a>, affine un modèle <a href="https://docs.ultralytics.com/models/yolov8#overview" target="_blank" rel="noreferrer">YOLOv8</a>, et exporte les poids <code>.onnx</code> intégrés au SPA.</li></ul><div class="tip custom-block"><p class="custom-block-title">Pourquoi sans backend</p><p>Les modèles <a href="https://docs.ultralytics.com/models/yolov8#overview" target="_blank" rel="noreferrer">YOLOv8n</a> sont suffisamment petits (~12 Mo chacun) pour tourner côté client via <a href="https://webassembly.org/" target="_blank" rel="noreferrer">WebAssembly</a>.</p></div>',5)])])}const _=r(s,[["render",i]]);export{g as __pageData,_ as default};
